begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api;
set local search_path=extensions,pg_catalog;
select no_plan();
insert into app.entitlements(school_id,code,enabled,effective_from)select s.id,c.code,true,'2026-09-01'from app.schools s cross join(values('curriculum'),('learning'),('assessment'))c(code)on conflict(school_id,code)do update set enabled=true;
select ok(to_regclass('app.marking_revisions') is not null,'draft marks persist separately');
select ok(to_regclass('app.result_revisions') is not null,'released immutable result history persists');
select ok(to_regclass('app.academic_evidence') is not null,'source evidence persists');
select ok(to_regclass('app.current_results') is not null,'current projection has released pointer');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app' and c.relname in('school_custom_references','marking_revisions','result_revisions','academic_evidence','current_results') and(not c.relrowsecurity or not c.relforcerowsecurity)),'academic tables force RLS');
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Academic golden','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score)values('10000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Numeric golden','Write',10);
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Immutable source');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score)values('10000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Unmapped numeric','Write',10);
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000012','Unmapped immutable source');
create temporary table academic_ids(reference_id uuid,mark_id uuid,result_id uuid);
grant select,insert,update on academic_ids to cuevo_api;
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
select throws_ok($$select internal.mark_submission('72000000-0000-4000-8000-000000000002',5,'Unmapped',1,0,true)$$,'22023',null,'missing approved reference blocks mark before immutable revision');
select is((select count(*)from app.marking_revisions where submission_id='72000000-0000-4000-8000-000000000002'),0::bigint,'failed unmapped mark leaves reference configuration recoverable');
insert into academic_ids(reference_id)select internal.create_school_reference('School objective','Synthetic objective','school-golden-1');
select throws_ok($$select internal.approve_school_reference((select reference_id from academic_ids))$$,'42501',null,'teacher cannot approve own academic context');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);select internal.approve_school_reference((select reference_id from academic_ids));
reset role;
select throws_ok($$update app.school_custom_references set title='Changed authority'where id=(select reference_id from academic_ids)$$,'55000',null,'approved reference cannot change');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.link_assessment_reference('71000000-0000-4000-8000-000000000001',(select reference_id from academic_ids),1);
select lives_ok($$select internal.link_assessment_reference('71000000-0000-4000-8000-000000000002',(select reference_id from academic_ids),1)$$,'reference can be linked after rejected unmapped mark');
select lives_ok($$select internal.mark_submission('72000000-0000-4000-8000-000000000002',5,'Recovered marking',2,0,true)$$,'linked assessment can now be marked');
select throws_ok($$select internal.mark_submission('72000000-0000-4000-8000-000000000001',null,'Missing',2,0,true)$$,'22023',null,'missing score is not zero');
select throws_ok($$select internal.mark_submission('72000000-0000-4000-8000-000000000001',11,'Out of range',2,0,true)$$,'22023',null,'score bound enforced');
select throws_ok($$select internal.mark_submission('72000000-0000-4000-8000-000000000001',5,'No source',2,0,false)$$,'22023',null,'source evidence explicitly required');
update academic_ids set mark_id=internal.mark_submission('72000000-0000-4000-8000-000000000001',0,'Zero legitimate',2,0,true);
select throws_ok($$select internal.mark_submission('72000000-0000-4000-8000-000000000001',1,'Stale',2,0,true)$$,'22023',null,'optimistic draft revision rejects stale marking');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is((select count(*)from app.marking_revisions where submission_id='72000000-0000-4000-8000-000000000001'),0::bigint,'student cannot read draft grade');
select is((select count(*)from app.current_results where submission_id='72000000-0000-4000-8000-000000000001'),0::bigint,'draft is absent from authoritative projection');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update academic_ids set result_id=internal.release_marking(mark_id,1,false);
select is(internal.release_marking((select mark_id from academic_ids),1,false),(select result_id from academic_ids),'new key duplicate release returns existing revision');
select throws_ok($$select internal.link_assessment_reference('71000000-0000-4000-8000-000000000001',(select reference_id from academic_ids),2)$$,'22023',null,'used assessment reference version frozen');
reset role;
select is((select count(*)from app.result_revisions where submission_id='72000000-0000-4000-8000-000000000001'),1::bigint,'one immutable released revision');
select is((select count(*)from app.academic_evidence where source_object_id='72000000-0000-4000-8000-000000000001'),1::bigint,'one source evidence per release');
select throws_ok($$update app.result_revisions set score=9 where submission_id='72000000-0000-4000-8000-000000000001'$$,'55000',null,'released result cannot overwrite history');
select throws_ok($$update app.assessments set max_score=20 where id='71000000-0000-4000-8000-000000000001'$$,'55000',null,'used native assessment scale cannot change');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select count(*)from app.result_revisions where submission_id='72000000-0000-4000-8000-000000000001'),0::bigint,'parent has no default released access');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
savepoint atomic_release;
select internal.begin_command('atomic-academic-golden','result.release','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef');
update academic_ids set mark_id=internal.mark_submission('72000000-0000-4000-8000-000000000001',6,'Correction',2,1,true);
select internal.release_marking((select mark_id from academic_ids),2,true);
select internal.append_audit('result.release','result',(select result_id from academic_ids),'atomic-academic-golden','succeeded','{}');
select internal.enqueue_event('result.released','result',(select result_id from academic_ids),2,'{}','atomic-academic-golden');
rollback to atomic_release;
reset role;
select is((select count(*)from app.result_revisions where submission_id='72000000-0000-4000-8000-000000000001'),1::bigint,'failed transaction leaves no partial released correction');
select is((select count(*)from app.academic_evidence where source_object_id='72000000-0000-4000-8000-000000000001'),1::bigint,'failed transaction leaves no correction evidence');
select is((select count(*)from internal.audit_events where request_id='atomic-academic-golden'),0::bigint,'failed academic transaction leaves no release audit');
select is((select count(*)from internal.outbox_events where deduplication_key='atomic-academic-golden'),0::bigint,'failed academic transaction leaves no orphan event');
select is((select count(*)from internal.idempotency_keys where key='atomic-academic-golden'),0::bigint,'failed academic transaction leaves no reservation');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.rolname in('anon','authenticated','service_role','cuevo_worker')where n.nspname='app'and c.relname in('school_custom_versions','school_custom_references','marking_revisions','result_revisions','academic_evidence','current_results')and has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE')),'academic records private from Data API and AI worker');
select * from finish();
rollback;
